std::string moniVersionname = "v1.1";

namespace {
const char* kShockConfigVersionKey = "模拟振配置版本";

bool ParseShockConfigVersionLine(const std::string& line, std::string* outVersion) {
	const std::string prefix = std::string(kShockConfigVersionKey) + "=";
	if (line.rfind(prefix, 0) != 0) {
		return false;
	}
	*outVersion = line.substr(prefix.size());
	while (!outVersion->empty()) {
		char tail = outVersion->back();
		if (tail == '\r' || tail == ';' || tail == ' ' || tail == '\t') {
			outVersion->pop_back();
			continue;
		}
		break;
	}
	return true;
}

void WriteShockConfigVersionLine(std::ofstream& file) {
	file << kShockConfigVersionKey << "=" << moniVersionname << "\n";
}
} // namespace
