static int VkToHidKey(int vk) {
	for (const auto& map : kVkToHidMap) {
		if (map.vk == vk) {
			return map.hid;
		}
	}
	return 0;
}

static int HidToVkKey(int hid) {
	for (const auto& map : kVkToHidMap) {
		if (map.hid == hid) {
			return map.vk;
		}
	}
	return 0;
}

static bool IsMouseVkKey(int vk) {
	return vk == VK_LBUTTON
		|| vk == VK_RBUTTON
		|| vk == VK_MBUTTON
		|| vk == VK_XBUTTON1
		|| vk == VK_XBUTTON2;
}

static const char* GetMouseVkName(int vk) {
	switch (vk) {
	case VK_LBUTTON:
		return "MouseLeft";
	case VK_RBUTTON:
		return "MouseRight";
	case VK_MBUTTON:
		return "MouseMiddle";
	case VK_XBUTTON1:
		return "MouseX1";
	case VK_XBUTTON2:
		return "MouseX2";
	default:
		return "Mouse";
	}
}
