void 判断Kmbox配置(const std::string& line)
{
	std::istringstream iss(line);
	std::string token;
	std::string paramName;
	//float paramValue;
	if (std::getline(iss, token, '='))
	{
		paramName = token;
		if (std::getline(iss, token))
		{
			//paramValue = std::stof(token); Port UUID 端口号 波特率 DIP DPort RANDOM
			if (paramName.find("IP") == 0) { strcpy(Function::Kmbox::Net::IP, token.c_str()); /*printf("%s\n", Function::Kmbox::Net::IP);*/ }
			if (paramName.find("Port") == 0) { strcpy(Function::Kmbox::Net::Port, token.c_str()); /*printf("%s\n", Function::Kmbox::Net::Port);*/ }
			if (paramName.find("UUID") == 0) { strcpy(Function::Kmbox::Net::mac, token.c_str()); /*printf("%s\n", Function::Kmbox::Net::mac);*/ }

			if (paramName.find("端口号") == 0) { strcpy(Function::Kmbox::B_Pro::PorttextBuffer, token.c_str()); }
			if (paramName.find("波特率") == 0) { strcpy(Function::Kmbox::B_Pro::SpeedBuffer, token.c_str()); }

			if (paramName.find("DIP") == 0) { strcpy(Function::Kmbox::DhzBox_Lite::IP, token.c_str()); }
			if (paramName.find("DPort") == 0) { strcpy(Function::Kmbox::DhzBox_Lite::Port, token.c_str());  }
			if (paramName.find("RANDOM") == 0) { strcpy(Function::Kmbox::DhzBox_Lite::RANDOM, token.c_str()); }
		}
	}
}
void 读取Kmbox配置()
{
	std::ifstream file("Kmbox.ini");
	if (file.is_open())
	{
		std::string line;
		while (std::getline(file, line))
		{
			判断Kmbox配置(line);
		}

		file.close();
	}
}

inline void SaveKeyBinds(const std::string& path = "keybinds.json") {
	nlohmann::json j;
	for (auto& [id, b] : KeyBinds::binds)
		j[id] = { {"keyCode", b.keyCode}, {"keyName", b.keyName} };
	std::ofstream(path) << j.dump(4);
}

inline void LoadKeyBinds(const std::string& path = "keybinds.json") {
	std::ifstream f(path);
	if (!f.is_open()) return;
	nlohmann::json j; f >> j;
	for (auto& [id, b] : KeyBinds::binds) {
		if (j.contains(id)) {
			b.keyCode = j[id]["keyCode"];
			b.keyName = j[id]["keyName"];
		}
	}
}
