void MENUKEY(){

	using namespace KeyBinds;

	if (mem.GetKeyboard()->IsKeyDown(binds["MENU_TOGGLE"].keyCode) || GetAsyncKeyState(binds["MENU_TOGGLE"].keyCode)) {
		Function::ESP::菜单 = !Function::ESP::菜单;
		Sleep(150);
	}

	if (mem.GetKeyboard()->IsKeyDown(binds["MENU_TOGGLE_2"].keyCode) || GetAsyncKeyState(binds["MENU_TOGGLE_2"].keyCode)) {
		Function::ESP::菜单_2 = !Function::ESP::菜单_2;
		Sleep(150);
	}

	if (mem.GetKeyboard()->IsKeyDown(binds["EXIT_APP"].keyCode) || GetAsyncKeyState(binds["EXIT_APP"].keyCode) & 0x8000) {
		VMMDLL_Close(mem.vHandle);
		Sleep(600);
		exit(0);
	}

	if (mem.GetKeyboard()->IsKeyDown(binds["F_SHOCKKNIFE"].keyCode) || GetAsyncKeyState(binds["F_SHOCKKNIFE"].keyCode)) {
		Function::Shock::F_ShockKnife = !Function::Shock::F_ShockKnife;
		Sleep(150);
	}

	if (mem.GetKeyboard()->IsKeyDown(binds["IS_DODGE"].keyCode) || GetAsyncKeyState(binds["IS_DODGE"].keyCode)) {
		Function::HeroActivation::IsDodge = !Function::HeroActivation::IsDodge;
		Sleep(150);
	}

	if (mem.GetKeyboard()->IsKeyDown(binds["AIMBOT_TOGGLE"].keyCode) || GetAsyncKeyState(binds["AIMBOT_TOGGLE"].keyCode)) {
		Function::AiMBot::AiMBotState = !Function::AiMBot::AiMBotState;
		Sleep(150);
	}
	
	if (mem.GetKeyboard()->IsKeyDown(binds["NO_SHOCKKNIFE_3A"].keyCode) || GetAsyncKeyState(binds["NO_SHOCKKNIFE_3A"].keyCode)) {
		Function::LogicKnife::NO_Shock_3A = !Function::LogicKnife::NO_Shock_3A;
		Sleep(150);
	}
}

void DrawRun()
{
	static uint64_t lastMatrixAddr = 0;
	
	MenuESP();
	MENUKEY();
	uint64_t addr = Offset::MatrixAddr ? Offset::MatrixAddr : lastMatrixAddr;
	if (!addr) {
		Global::WorldPtr.Character->GetCharacterManagerPtr();
		if (Global::WorldPtr.Character->CharacterManagerPtr) {
			const uint64_t newAddr = Tool::GetMatrixAddr(Global::WorldPtr.Character->CharacterManagerPtr);
			if (newAddr > 0x10000) {
				Offset::MatrixAddr = newAddr;
				addr = newAddr;
			}
		}
	}
	if (addr) {
		float tmp[4][4];
		mem.Read(addr, &tmp, sizeof(tmp));
		bool sane = true;
		float sum = 0.0f;
		for (int r = 0; r < 4 && sane; ++r) {
			for (int c = 0; c < 4; ++c) {
				const float v = tmp[r][c];
				if (!std::isfinite(v)) {
					sane = false;
					break;
				}
				sum += std::fabs(v);
			}
		}
		if (sane && sum > 0.001f) {
			std::memcpy(MATRIX, tmp, sizeof(tmp));
			lastMatrixAddr = addr;
		}
	}
	PlayerESP();
	ItemESP();
	InteractiveESP();
	this_thread::sleep_for(chrono::milliseconds(1));
}